typedef signed char S __attribute__((vector_size(16)));typedef unsigned char U __attribute__((vector_size(16)));
S add_sat_signed(S a,S b){return __builtin_elementwise_add_sat(a,b);}
U add_sat_unsigned(U a,U b){return __builtin_elementwise_add_sat(a,b);}
int add_sat_scalar(int a,int b){return __builtin_elementwise_add_sat(a,b);}
S sub_sat_signed(S a,S b){return __builtin_elementwise_sub_sat(a,b);}
U sub_sat_unsigned(U a,U b){return __builtin_elementwise_sub_sat(a,b);}
int sub_sat_scalar(int a,int b){return __builtin_elementwise_sub_sat(a,b);}
S min_signed(S a,S b){return __builtin_elementwise_min(a,b);}
U min_unsigned(U a,U b){return __builtin_elementwise_min(a,b);}
int min_scalar(int a,int b){return __builtin_elementwise_min(a,b);}
S max_signed(S a,S b){return __builtin_elementwise_max(a,b);}
U max_unsigned(U a,U b){return __builtin_elementwise_max(a,b);}
int max_scalar(int a,int b){return __builtin_elementwise_max(a,b);}
int promote(signed char a,signed char b){return __builtin_elementwise_add_sat(a,b);}
int read_values(volatile int*a,_Atomic int*b){return __builtin_elementwise_min(*a,*b);}

